def check_book_status(book_name, rel_path):
    full_path = os.path.join(base_path, rel_path)
    if not os.path.exists(full_path):
        return f"❌ {book_name}: Directory not found at {rel_path}"

    # Check for manuscript
    manuscript_extensions = ['.md', '.txt', '.docx']
    manuscript_found = False
    for ext in manuscript_extensions:
        if any(f.endswith(ext) for f in os.listdir(full_path) if os.path.isfile(os.path.join(full_path, f))):
            manuscript_found = True
            break

    # Check for book-sources directory (common in the structure)
    book_sources_path = os.path.join(full_path, 'book-sources')
    if os.path.exists(book_sources_path):
        # Look for chapter files
        chapter_files = [f for f in os.listdir(book_sources_path) if f.startswith('Chapter_') and f.endswith('.md')]
        if chapter_files:
            manuscript_found = True

    # Check for cover
    cover_found = False
    cover_files = [f for f in os.listdir(full_path) if f.lower().startswith('cover') and (f.lower().endswith('.png') or f.lower().endswith('.jpg') or f.lower().endswith('.jpeg'))]
    if cover_files:
        cover_found = True

    # Check for output directory and EPUB/PDF
    output_path = os.path.join(full_path, 'output')
    epub_ready = False
    pdf_ready = False
    if os.path.exists(output_path):
        for f in os.listdir(output_path):
            if f.lower().endswith('.epub'):
                epub_ready = True
            if f.lower().endswith('.pdf'):
                pdf_ready = True

    # Also check for publishing package
    publishing_path = os.path.join(full_path, '*Publishing*Package*')
    # We'll do a simple check for any directory with 'Publishing' in the name
    for item in os.listdir(full_path):
        if os.path.isdir(os.path.join(full_path, item)) and 'publishing' in item.lower():
            # Check inside for EPUB/PDF
            item_path = os.path.join(full_path, item)
            for f in os.listdir(item_path):
                if f.lower().endswith('.epub'):
                    epub_ready = True
                if f.lower().endswith('.pdf'):
                    pdf_ready = True

    status_parts = []
    if manuscript_found:
        status_parts.append("📝 Manuscript: ready")
    else:
        status_parts.append("📝 Manuscript: missing or incomplete")

    if cover_found:
        status_parts.append("🖼️ Cover: ready")
    else:
        status_parts.append("🖼️ Cover: missing")

    if epub_ready:
        status_parts.append("📚 EPUB: ready")
    else:
        status_parts.append("📚 EPUB: not ready")

    if pdf_ready:
        status_parts.append("📄 PDF: ready")
    else:
        status_parts.append("📄 PDF: not ready")

    # Determine if there's pending work
    pending = []
    if not manuscript_found:
        pending.append("manuscript")
    if not cover_found:
        pending.append("cover")
    if not epub_ready:
        pending.append("EPUB")
    if not pdf_ready:
        pending.append("PDF")

    pending_str = ", ".join(pending) if pending else "none"

    return f"✅ {book_name}\n  - " + "\n  - ".join(status_parts) + f"\n  - ⏳ Pending work: {pending_str}"

for book_name, rel_path in books:
    print(check_book_status(book_name, rel_path))
    print()"}
